const job = $json;
const payload = typeof job.payload === 'string' ? JSON.parse(job.payload) : (job.payload || {});
const failUntil = Number(payload.simulate_failure_until || 0);
const delivery_succeeded = Number(job.attempt_count) > failUntil;
return [{ json: {
  ...job,
  payload,
  delivery_succeeded,
  delivery_reference: delivery_succeeded ? `synthetic-${job.id}-${job.attempt_count}` : null,
  delivery_error: delivery_succeeded ? null : 'Synthetic transient delivery failure',
} }];
